// scripts/seed-clients.mjs
// Run: node scripts/seed-clients.mjs
import { createClient } from '@libsql/client'
import { readFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { dirname, join } from 'path'

// Load env manually
const envPath = join(dirname(fileURLToPath(import.meta.url)), '..', '.env.local')
try {
  const env = readFileSync(envPath, 'utf-8')
  env.split('\n').forEach(line => {
    const [k, ...v] = line.split('=')
    if (k && v.length) process.env[k.trim()] = v.join('=').trim().replace(/^["']|["']$/g, '')
  })
} catch { /* .env.local not found, use existing env */ }

const db = createClient({
  url: process.env.TURSO_DATABASE_URL,
  authToken: process.env.TURSO_AUTH_TOKEN,
})

// ─── Step 1: Add classification column if it doesn't exist ───────────────────
async function migrate() {
  console.log('📦  Running migration: add classification column...')
  try {
    await db.execute(`ALTER TABLE clients ADD COLUMN classification TEXT DEFAULT 'AL DÍA'`)
    console.log('✅  Column classification added successfully.')
  } catch (e) {
    if (String(e).includes('duplicate column') || String(e).includes('already exists')) {
      console.log('ℹ️   Column classification already exists — skipping.')
    } else {
      throw e
    }
  }
}

// ─── Step 2: Clear existing clients ──────────────────────────────────────────
async function clearClients() {
  const existing = await db.execute('SELECT COUNT(*) as c FROM clients')
  const count = Number(existing.rows[0].c)
  if (count > 0) {
    console.log(`⚠️   Found ${count} existing clients. Clearing to avoid duplicates...`)
    await db.execute('DELETE FROM clients')
    console.log('🗑️   Cleared.')
  } else {
    console.log('📭  No existing clients — fresh import.')
  }
}

