async function seedClients() {
  console.log(`\n🚀  Importing ${CLIENTS.length} clients in batches of 50...`)
  const BATCH_SIZE = 50
  let inserted = 0
  let errors = 0

  for (let i = 0; i < CLIENTS.length; i += BATCH_SIZE) {
    const batch = CLIENTS.slice(i, i + BATCH_SIZE)
    const stmts = batch.map(c => ({
      sql: `INSERT INTO clients 
              (name, cellphone, address, reference, plan, plan_value, notes, status, classification)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      args: [c.name, c.cellphone, c.address, c.reference, c.plan, c.plan_value, c.notes, c.status, c.classification]
    }))
    try {
      await db.batch(stmts, 'write')
      inserted += batch.length
      process.stdout.write(`\r   Progress: ${inserted}/${CLIENTS.length}`)
    } catch (e) {
      console.error(`\n❌  Batch ${Math.floor(i/BATCH_SIZE)+1} error:`, e.message)
      errors++
    }
  }
  console.log(`\n\n✅  Done! Inserted: ${inserted} | Errors: ${errors}`)
}

// ─── Step 4: Verify ───────────────────────────────────────────────────────────
async function verify() {
  const total = await db.execute('SELECT COUNT(*) as c FROM clients')
  const byClass = await db.execute(`
    SELECT classification, COUNT(*) as n 
    FROM clients 
    GROUP BY classification 
    ORDER BY n DESC
  `)
  console.log(`\n📊  Verification — Total in DB: ${total.rows[0].c}`)
  console.log('─'.repeat(50))
  byClass.rows.forEach(r => {
    console.log(`   ${String(r.classification).padEnd(35)} ${r.n}`)
  })
}

// ─── Main ─────────────────────────────────────────────────────────────────────
async function main() {
  console.log('═'.repeat(55))
  console.log('  MEDIFIBRA — Cliente Seed Script')
  console.log('═'.repeat(55))
  await migrate()
  await clearClients()
  await seedClients()
  await verify()
  console.log('\n🎉  Import complete! Run npm run dev to see the data.')
  process.exit(0)
}

main().catch(e => { console.error('FATAL:', e); process.exit(1) })